 desc=f"{id} source-verified evidence guide: {e['title']}. Document context, GAH source viewer, DOJ release index, and evidentiary limits."
 def esc(s):return html.escape(s,quote=True)
 jsonld={"@context":"https://schema.org","@type":"CreativeWork","name":f"{id}: {e['title']}","description":desc,"identifier":id,"url":base,"mainEntityOfPage":base,"isAccessibleForFree":True,"publisher":{"@type":"Organization","name":"Grok Archive Hub"},"citation":source,"dateModified":"2026-10-21"}
 sections=[
 ("Document identification",f"The archival identifier is {id}. The document is described as {e['title']}. Source collection: {e['source']}; record chronology: {e['date']}. The canonical GAH page is an editorial source guide, not a claim that a Google result or fragment alone authenticates the underlying record."),
 ("What the available source establishes",e['evidence']),
 ("What this document cannot establish",e['limits']),
 ("How to verify and use the record",e['context']+" Start with the preserved archive viewer; if available, compare page images with the DOJ source-index entry. Cite the EFTA number, a visible page or document date, and the source-level limitations. GAH separates documented statements from inferences and unresolved gaps.")
 ]
 content='\n'.join('<section><h2>'+esc(h)+'</h2><p>'+esc(p)+'</p></section>' for h,p in sections)
 def link(href,label):return f'<a href="{esc(href)}">{esc(label)}</a>'
 viewer = (link('/pdf-lite?id='+id,'Read archived PDF in GAH viewer')+' · ') if id not in {'EFTA00000468','EFTA01703108'} else ''
 links=f"<p class='links'>{viewer}{link(source,'Official DOJ source index')} · {link(e['related'],'Related source-verified investigation')} · {link('/guides/how-to-search-epstein-files','How to check an EFTA number')}</p>"
